// Navigation et menu mobile
const toggle = document.querySelector('.menu-toggle');
const nav = document.querySelector('#nav');
toggle?.addEventListener('click', () => {
  const open = nav.classList.toggle('open');
  toggle.setAttribute('aria-expanded', String(open));
});
nav?.querySelectorAll('a').forEach(link => link.addEventListener('click', () => {
  nav.classList.remove('open');
  toggle?.setAttribute('aria-expanded', 'false');
}));
if(document.querySelector('#year')) document.querySelector('#year').textContent = new Date().getFullYear();

const progressBar = document.querySelector('#scroll-progress-bar');
const navLinks = [...document.querySelectorAll('.nav a[href^="#"]')];
const sections = [...document.querySelectorAll('main section[id]')];
function updateScrollUI() {
  const scrollable = document.documentElement.scrollHeight - window.innerHeight;
  if (progressBar) progressBar.style.width = `${scrollable > 0 ? Math.min(100, 100 * window.scrollY / scrollable) : 0}%`;
  const current = [...sections].reverse().find(section => section.getBoundingClientRect().top <= 160) || sections[0];
  navLinks.forEach(link => {
    const active = link.getAttribute('href') === `#${current.id}`;
    link.classList.toggle('active', active);
    if (active) link.setAttribute('aria-current', 'location');
    else link.removeAttribute('aria-current');
  });
}
window.addEventListener('scroll', updateScrollUI, { passive: true });
window.addEventListener('resize', updateScrollUI);
updateScrollUI();

document.querySelectorAll('.filter-btn').forEach(button => button.addEventListener('click', () => {
 const category = button.dataset.filter;
 document.querySelectorAll('.filter-btn').forEach(b => { const active=b===button;b.classList.toggle('selected',active);b.setAttribute('aria-pressed',String(active)); });
 document.querySelectorAll('.filter-item').forEach(item => {item.hidden = category !== 'all' && item.dataset.category !== category;});
}));


/* Navigation vers les catégories de médiation */

document.querySelectorAll("[data-mediation-filter]").forEach(link => {
  link.addEventListener("click", () => {
    const category = link.dataset.mediationFilter;

    const filterButton = document.querySelector(
      `.filter-btn[data-filter="${category}"]`
    );

    if (filterButton) {
      filterButton.click();
    }
  });
});


