const originalNodes = [...document.querySelectorAll("main,header,footer")].flatMap(root=>{const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let n,out=[];while(n=walker.nextNode())if(n.nodeValue.trim())out.push([n,n.nodeValue]);return out});
let english=false;document.querySelector("#lang-toggle")?.addEventListener("click",()=>{english=!english;document.documentElement.lang=english?"en":"fr";originalNodes.forEach(([node,fr])=>{const t=fr.trim();node.nodeValue=english&&dictionary[t]?fr.replace(t,dictionary[t]):fr});const b=document.querySelector("#lang-toggle");b.textContent=english?"FR":"EN";b.setAttribute("aria-label",english?"Passer en français":"Switch to English");});

document.querySelectorAll('.nav-drop-trigger').forEach(button => button.addEventListener('click', () => { const parent=button.parentElement;const expanded=parent.classList.toggle('expanded');button.setAttribute('aria-expanded',String(expanded)); }));

const translatedAttrs = [...document.querySelectorAll('[alt],[aria-label],[title],[placeholder],meta[name="description"]')].flatMap(el=>['alt','aria-label','title','placeholder','content'].filter(a=>el.hasAttribute(a) && (a!=='content'||el.matches('meta[name="description"]'))).map(a=>[el,a,el.getAttribute(a)]));
const attrTranslations = {"Atlas — accueil":"Atlas — home","Navigation principale":"Main navigation","Passer en français":"Switch to French","Portrait d’Atlas":"Portrait of Atlas","Portrait d’Atlas en extérieur":"Outdoor portrait of Atlas","Enregistrement de l’émission radio Les femmes dans la science":"Recording of the Women in Science radio show","Affiche du jeu de piste Cuisine ta science":"Cuisine ta science science trail poster","Animation du jeu de piste Cuisine ta science":"Facilitating the Cuisine ta science activity","Aperçu de la ressource liée":"Preview of the linked resource"};
const originalLangToggle = document.querySelector('#lang-toggle');
originalLangToggle?.addEventListener('click',()=>{translatedAttrs.forEach(([el,a,fr])=>el.setAttribute(a,english?(attrTranslations[fr]||dictionary[fr]||fr):fr));document.title=english?'Atlas Thébault Guiochon · Research & science communication':'Atlas Thébault Guiochon · Recherche & médiation scientifique';});

const themeButton=document.querySelector('#theme-toggle');
const themeQuery=window.matchMedia('(prefers-color-scheme: dark)');
const storedTheme=localStorage.getItem('atlas-theme');
if(storedTheme==='light'||storedTheme==='dark')document.documentElement.dataset.theme=storedTheme;
function updateThemeButton(){const dark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&themeQuery.matches);if(themeButton){themeButton.textContent=dark?'☀':'☾';themeButton.setAttribute('aria-label',dark?'Activer le thème clair':'Activer le thème sombre');}}
themeButton?.addEventListener('click',()=>{const dark=document.documentElement.dataset.theme==='dark'||(!document.documentElement.dataset.theme&&themeQuery.matches);const next=dark?'light':'dark';document.documentElement.dataset.theme=next;localStorage.setItem('atlas-theme',next);updateThemeButton();});
themeQuery.addEventListener?.('change',updateThemeButton);updateThemeButton();

